class NumArray {
    private long[] pre;                 // pre[i] = a[0] + ... + a[i-1]
    public NumArray(int[] a) {
        pre = new long[a.length + 1];
        for (int i = 0; i < a.length; i++) pre[i + 1] = pre[i] + a[i];
    }
    public int sumRange(int l, int r) { // inclusive l..r
        return (int)(pre[r + 1] - pre[l]);
    }
}
